PACKAGE BODY PKG_BANK AS
  PROCEDURE GET_CUSTOMER (P_CUSTOMER_ID IN NUMBER) AS
  BEGIN
    FOR REC IN (SELECT * FROM CUSTOMER WHERE CUSTOMER_ID = P_CUSTOMER_ID) LOOP
      DBMS_OUTPUT.PUT_LINE('Customer ID: ' || REC.CUSTOMER_ID);
    END LOOP;
  END GET_CUSTOMER;

  FUNCTION GET_TOTAL_CUSTOMERS RETURN NUMBER AS
    V_TOTAL NUMBER;
  BEGIN
    SELECT COUNT(*) INTO V_TOTAL FROM CUSTOMER;
    RETURN V_TOTAL;
  END GET_TOTAL_CUSTOMERS;
END PKG_BANK;
